import{_ as t,o as a,c as r,a2 as e}from"./chunks/framework.A5mep7Fe.js";const h=JSON.parse('{"title":"🗄️ 02 · 后端（AI 服务架构）","description":"","frontmatter":{},"headers":[],"relativePath":"07-开发岗-前后端与全栈/02-后端.md","filePath":"07-开发岗-前后端与全栈/02-后端.md","lastUpdated":1786806808000}'),l={name:"07-开发岗-前后端与全栈/02-后端.md"};function n(i,o,s,c,d,g){return a(),r("div",null,[...o[0]||(o[0]=[e('<h1 id="🗄️-02-·-后端-ai-服务架构" tabindex="-1">🗄️ 02 · 后端（AI 服务架构） <a class="header-anchor" href="#🗄️-02-·-后端-ai-服务架构" aria-label="Permalink to &quot;🗄️ 02 · 后端（AI 服务架构）&quot;">​</a></h1><blockquote><p>AI 应用的后端不是普通 CRUD——要管模型调用、流式、缓存、成本、权限。本篇讲 AI 后端的设计要点。</p></blockquote><hr><h2 id="一、核心考点-通用" tabindex="-1">一、核心考点（通用） <a class="header-anchor" href="#一、核心考点-通用" aria-label="Permalink to &quot;一、核心考点（通用）&quot;">​</a></h2><ul><li><strong>架构</strong>：分层、微服务、DDD、事件驱动。</li><li><strong>API</strong>：REST / gRPC、鉴权（JWT/OAuth）、限流、幂等。</li><li><strong>数据库</strong>：关系型（PostgreSQL/MySQL）、NoSQL（MongoDB/Redis）、选型。</li><li><strong>缓存</strong>：Redis 命中率、击穿/雪崩/穿透。</li><li><strong>消息队列</strong>：Kafka/RabbitMQ，异步解耦。</li></ul><h2 id="二、ai-后端专属设计" tabindex="-1">二、AI 后端专属设计 <a class="header-anchor" href="#二、ai-后端专属设计" aria-label="Permalink to &quot;二、AI 后端专属设计&quot;">​</a></h2><ul><li><strong>模型网关</strong>：统一封装多家 LLM API，做路由/降级/成本统计。</li><li><strong>流式转发</strong>：后端消费上游 SSE，转给前端（见 <code>06-Java</code>/<code>04-Go</code>）。</li><li><strong>Prompt/知识库管理</strong>：模板存储、版本、AB；文档 ETL 管线。</li><li><strong>多租户与权限</strong>：隔离不同客户的语料/对话（RAG 安全关键）。</li><li><strong>成本控制</strong>：token 计量、配额、缓存重复请求。</li><li><strong>异步任务</strong>：长任务（文档入库、批量推理）用队列 + 状态轮询。</li></ul><h2 id="三、高频追问" tabindex="-1">三、高频追问 <a class="header-anchor" href="#三、高频追问" aria-label="Permalink to &quot;三、高频追问&quot;">​</a></h2><p><strong>Q1：AI 后端和普通后端最大区别？</strong></p><blockquote><p>多了「不确定性 + 高延迟 + 高成本」：模型调用慢且贵、结果非确定性，需要流式、缓存、降级、成本计量与并发控制，普通 CRUD 没有这些。</p></blockquote><p><strong>Q2：怎么做 LLM 调用的缓存降本？</strong></p><blockquote><p>语义缓存（相似问题复用答案）、精确缓存（相同 prompt 命中）、热点知识预生成；配合模型路由（小模型处理简单问题）。</p></blockquote><p><strong>Q3：RAG 的多租户怎么隔离？</strong></p><blockquote><p>向量库按 tenant_id 过滤/独立 collection、行级权限、对话与文档归属校验，防止跨客户数据泄漏。</p></blockquote><hr><p>➡️ 下一步：<a href="./03-测试">03-测试</a></p>',16)])])}const u=t(l,[["render",n]]);export{h as __pageData,u as default};
